
package com.aiassistant.blindpeople.distance

import com.aiassistant.blindpeople.YOLODetection
import kotlin.math.ceil
import kotlin.math.floor
import kotlin.math.max
import kotlin.math.min

/**
 * A metric depth map generated by Depth Anything V2.
 *
 * Values are stored in row-major order:
 * index = y * width + x
 *
 * All depth measurements are in meters.
 */
data class MetricDepthMap(
    val width: Int,
    val height: Int,
    val valuesMeters: FloatArray
) {
    init {
        require(width > 0 && height > 0) {
            "Depth map dimensions must be positive."
        }

        require(
            valuesMeters.size == width * height
        ) {
            "Depth array size does not match dimensions."
        }
    }
}

/**
 * Describes the consistency of sampled depth values.
 *
 * CONSISTENT does not guarantee physical accuracy.
 */
enum class DepthReliability {
    CONSISTENT,
    VARIABLE,
    UNAVAILABLE
}

data class AutomaticObjectDistance(
    val label: String,
    val detectionConfidence: Float,
    val estimatedMeters: Float?,
    val estimatedInches: Float?,
    val nearPercentileInches: Float?,
    val spreadInches: Float?,
    val sampledPixels: Int,
    val reliability: DepthReliability
)

/**
 * Automatically estimates an object's depth by
 * associating a YOLO detection with a metric depth map.
 *
 * No manual calibration or known object dimensions
 * are required.
 */
class AutomaticObjectDistanceEstimator {

    companion object {
        private const val METERS_TO_INCHES = 39.37007874f

        private const val MIN_DEPTH_METERS = 0.20f
        private const val MAX_DEPTH_METERS = 20.0f

        private const val MIN_SAMPLES = 16
        private const val BOX_INSET = 0.20f
    }

    fun estimate(
        detections: List<YOLODetection>,
        depthMap: MetricDepthMap,
        cameraWidth: Int,
        cameraHeight: Int
    ): List<AutomaticObjectDistance> {

        require(cameraWidth > 0 && cameraHeight > 0) {
            "Camera dimensions must be positive."
        }

        return detections.map { detection ->
            estimateSingle(
                detection = detection,
                depthMap = depthMap,
                cameraWidth = cameraWidth,
                cameraHeight = cameraHeight
            )
        }
    }

    private fun estimateSingle(
        detection: YOLODetection,
        depthMap: MetricDepthMap,
        cameraWidth: Int,
        cameraHeight: Int
    ): AutomaticObjectDistance {

        fun unavailable(): AutomaticObjectDistance {
            return AutomaticObjectDistance(
                label = detection.label,
                detectionConfidence = detection.confidence,
                estimatedMeters = null,
                estimatedInches = null,
                nearPercentileInches = null,
                spreadInches = null,
                sampledPixels = 0,
                reliability = DepthReliability.UNAVAILABLE
            )
        }

        val box = detection.boundingBox

        if (
            !box.left.isFinite() ||
            !box.top.isFinite() ||
            !box.right.isFinite() ||
            !box.bottom.isFinite() ||
            box.width() <= 0f ||
            box.height() <= 0f
        ) {
            return unavailable()
        }

        val scaleX =
            depthMap.width.toFloat() / cameraWidth.toFloat()

        val scaleY =
            depthMap.height.toFloat() / cameraHeight.toFloat()

        val insetX = box.width() * BOX_INSET
        val insetY = box.height() * BOX_INSET

        val left = floor(
            (box.left + insetX) * scaleX
        ).toInt().coerceIn(0, depthMap.width)

        val top = floor(
            (box.top + insetY) * scaleY
        ).toInt().coerceIn(0, depthMap.height)

        val right = ceil(
            (box.right - insetX) * scaleX
        ).toInt().coerceIn(0, depthMap.width)

        val bottom = ceil(
            (box.bottom - insetY) * scaleY
        ).toInt().coerceIn(0, depthMap.height)

        if (right <= left || bottom <= top) {
            return unavailable()
        }

        val values = ArrayList<Float>()

        for (y in top until bottom) {
            for (x in left until right) {

                val depth = depthMap.valuesMeters[
                    y * depthMap.width + x
                ]

                if (
                    depth.isFinite() &&
                    depth >= MIN_DEPTH_METERS &&
                    depth <= MAX_DEPTH_METERS
                ) {
                    values.add(depth)
                }
            }
        }

        if (values.size < MIN_SAMPLES) {
            return unavailable()
        }

        values.sort()

        val medianMeters = percentile(values, 0.50f)
        val p20Meters = percentile(values, 0.20f)
        val p80Meters = percentile(values, 0.80f)

        val spreadMeters = p80Meters - p20Meters

        val allowedSpreadMeters = max(
            0.15f,
            medianMeters * 0.20f
        )

        val reliability = if (
            spreadMeters <= allowedSpreadMeters
        ) {
            DepthReliability.CONSISTENT
        } else {
            DepthReliability.VARIABLE
        }

        return AutomaticObjectDistance(
            label = detection.label,
            detectionConfidence = detection.confidence,
            estimatedMeters = medianMeters,
            estimatedInches =
                medianMeters * METERS_TO_INCHES,
            nearPercentileInches =
                p20Meters * METERS_TO_INCHES,
            spreadInches =
                spreadMeters * METERS_TO_INCHES,
            sampledPixels = values.size,
            reliability = reliability
        )
    }

    private fun percentile(
        sortedValues: List<Float>,
        fraction: Float
    ): Float {

        require(sortedValues.isNotEmpty())

        val position =
            fraction.coerceIn(0f, 1f) *
                    (sortedValues.size - 1)

        val lower = floor(position).toInt()

        val upper = min(
            lower + 1,
            sortedValues.lastIndex
        )

        val weight = position - lower

        return sortedValues[lower] * (1f - weight) +
                sortedValues[upper] * weight
    }
}
